import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.C9XHwBqm.js";const p=JSON.parse('{"title":"What Kevin AI is","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1795642929000}'),n={name:"index.md"};function i(s,e,d,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-kevin-ai-is" tabindex="-1">What Kevin AI is <a class="header-anchor" href="#what-kevin-ai-is" aria-label="Permalink to &quot;What Kevin AI is&quot;">​</a></h1><p>Kevin AI is a <strong>private, local-first</strong> AI assistant: the chat UI runs on your machine, conversations stay in the browser, and the language model runs on a small home server (an OptiPlex) reached through SSH tunnels. There is no telemetry and no third-party script in the page — the Content-Security-Policy is <code>&#39;self&#39;</code> only.</p><h2 id="three-parts" tabindex="-1">Three parts <a class="header-anchor" href="#three-parts" aria-label="Permalink to &quot;Three parts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>What it is</th><th>Where it lives</th></tr></thead><tbody><tr><td><strong>Engine</strong></td><td>C99 inference (<code>lm-serve</code>) or llama.cpp (<code>llama-server</code>)</td><td>Model host, port <strong>8080</strong></td></tr><tr><td><strong>Tools</strong></td><td>MCP servers, web search, projects</td><td><code>tools/chat_tools.py</code> on <strong>8081</strong> (host) and optionally <strong>8082</strong> (Mac)</td></tr><tr><td><strong>Chat UI</strong></td><td>React app</td><td>Vite in <strong>dev</strong> (<code>5173</code>) or <code>tools/chat_server.py</code> in <strong>prod</strong> (<code>8000</code>)</td></tr></tbody></table><p>Interactive map of the repository: <a href="https://gitdiagram.com/marcfs31/kevin-ai" target="_blank" rel="noreferrer">gitdiagram.com/marcfs31/kevin-ai</a> (GitDiagram — AI overview; verify details against this guide and the source).</p><h2 id="read-next" tabindex="-1">Read next <a class="header-anchor" href="#read-next" aria-label="Permalink to &quot;Read next&quot;">​</a></h2><ol><li><a href="/kevin-ai/guide/overview.html">System overview</a> — how the pieces connect</li><li><a href="/kevin-ai/guide/vite-and-chat-server.html">Vite vs chat_server</a> — which UI server to open</li><li><a href="/kevin-ai/guide/apis.html">How the APIs are built</a> — no framework; three hand-rolled HTTP layers</li><li><a href="/kevin-ai/guide/models.html">How models run</a> — engines, IDs, tunnels</li><li><a href="/kevin-ai/guide/run-on-mac.html">Run the demo on the Mac</a> — ports and start commands</li></ol><p>The long-form product and install story remains in the <a href="https://github.com/marcfs31/kevin-ai/blob/main/README.md" target="_blank" rel="noreferrer">root README</a>. Engine roadmap: <a href="https://github.com/marcfs31/kevin-ai/blob/main/docs/PLAN.md" target="_blank" rel="noreferrer"><code>docs/PLAN.md</code></a>.</p>',8)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
